/// Callback conversion retains through its invoking operation, including host
/// Promise settlement. Detached work can still exchange ordinary references.
const callbackResourceEntrypointPrelude = r'''
WasmExternRef _callbackResourceRetainer(ResourceOperation? operation) {
  void retain(JSAny? reference) {
  if (reference == null) return;
  try {
    final control = _resourceControl(externRefForJSAny(reference)!.internalize().toObject());
    if (control == null) return;
    if (operation == null) {
      throw _CallbackThrown(_callbackStructureError(
          externRefForJSAny('callback resource'.toJS)!,
          externRefForJSAny('resource access requires an active bound call'.toJS)!,
          WasmI32.fromInt(0)));
    }
    operation.retain(control);
  } on _CallbackThrown catch (error) {
    _throwCallbackError(error.envelope);
  } catch (error) {
    _normalizeResourceError(error);
  }
  }
  return externRefForJSAny(((JSAny? reference, [JSAny? defaultId]) {
    if (defaultId == null) { retain(reference); }
    else {
      _visitValueDefaultReferences((defaultId as JSString).toDart, (value) {
        retain(WasmAnyRef.fromObject(value).externalize().toJS);
      });
    }
  }).toJS)!;
}
''';

/// Preserve exact host errors from callbacks, cancellation and shared bytes.
/// Shared allocation may be used internally even without a shared signature.
String withCallbackErrors(String source) => source
    .replaceFirst(
      'WasmExternRef? _normalizeError(Object error) {\n',
      'WasmExternRef? _normalizeError(Object error) {\n'
          '  if (error is _CallbackThrown) return _throwCallbackError(error.envelope);\n',
    )
    .replaceFirst(
      'void _failFuture(WasmExternRef capability, Object error, StackTrace stack, String context) {\n',
      'void _failFuture(WasmExternRef capability, Object error, StackTrace stack, String context) {\n'
          '  if (error is _CallbackThrown) { _rejectCallbackPromise(capability, error.envelope); return; }\n',
    )
    .replaceFirst(
      '    _throwFutureError(',
      '    error is _CallbackThrown ? _throwCallbackError(error.envelope) : _throwFutureError(',
    );

/// Future payload conversion is invoked under the host's exception handler so
/// JS boundary failures retain their original value instead of Dart boxing.
const futureEntrypointPrelude = r'''
@pragma('wasm:import', 'napi.retainPromise')
external void _retainPromise(WasmExternRef capability, WasmExternRef roots);
@pragma('wasm:import', 'napi.completePromise')
external void _completePromise(WasmExternRef capability, WasmExternRef? convert);
@pragma('wasm:import', 'napi.resolvePromiseValue')
external void _resolvePromiseValue(WasmExternRef capability, WasmExternRef? value);
@pragma('wasm:import', 'napi.failPromise')
external void _failPromise(WasmExternRef capability, WasmExternRef message, WasmExternRef stack);
@pragma('wasm:import', 'napi.throwFutureError')
external WasmExternRef? _throwFutureError(WasmExternRef message, WasmExternRef stack);

String _futureErrorMessage(Object error) {
  try { return error.toString(); }
  catch (_) { return 'Dart operation failed (error description unavailable)'; }
}

String _stackMessage(StackTrace stack) {
  try { return stack.toString(); }
  catch (_) { return 'Dart stack trace unavailable'; }
}

void _failFuture(WasmExternRef capability, Object error, StackTrace stack, String context) {
  // Discard the private Wasm void result with a statement, not an arrow return.
  _failPromise(capability, externRefForJSAny('$context: ${_futureErrorMessage(error)}'.toJS)!, externRefForJSAny(_stackMessage(stack).toJS)!);
}

WasmExternRef? _normalizeFutureError(Object error, StackTrace stack, String context) =>
    _throwFutureError(externRefForJSAny('$context: ${_futureErrorMessage(error)}'.toJS)!, externRefForJSAny(_stackMessage(stack).toJS)!);

void _observeFuture<T>(Future<T> future, WasmExternRef capability, String context, void Function(T)? convert) {
  var delivered = false;
  void fail(Object error, StackTrace stack) {
    if (delivered) return;
    delivered = true;
    _failFuture(capability, error, stack, context);
  }
  try {
    future.then<void>((value) {
      if (delivered) return;
      delivered = true;
      // The void converter delivers its raw externref with _resolvePromiseValue
      // under the host's exception handler. JSAny would erase JS undefined.
      _completePromise(capability, convert == null ? WasmExternRef.nullRef : externRefForJSAny((() { convert(value); }).toJS));
    }, onError: fail);
  } catch (error, stack) { fail(error, stack); }
}
''';

/// Stream snapshots cross the host boundary in a non-null envelope. Their raw
/// payload never passes through JSAny, which would collapse undefined to null.
const streamEntrypointPrelude = r'''
@pragma('wasm:import', 'napi.captureStreamItem')
external WasmExternRef _captureStreamItem(WasmExternRef convert, WasmI32 classId, WasmExternRef path);
@pragma('wasm:import', 'napi.writeStreamItem')
external void _writeStreamItem(WasmExternRef envelope, WasmExternRef? value);
@pragma('wasm:import', 'napi.streamItemThrew')
external WasmI32 _streamItemThrew(WasmExternRef envelope);
@pragma('wasm:import', 'napi.releaseStreamItem')
external void _releaseStreamItem(WasmExternRef envelope);
@pragma('wasm:import', 'napi.throwStreamError')
external WasmExternRef? _throwStreamError(WasmExternRef envelope);
@pragma('wasm:import', 'napi.throwStreamOverflow')
external WasmExternRef? _throwStreamOverflow(WasmExternRef message, WasmExternRef stack);
@pragma('wasm:import', 'napi.attachStreamDelivery')
external void _attachStreamDelivery(WasmExternRef capability, WasmExternRef release, WasmExternRef failed);
@pragma('wasm:import', 'napi.resolveStreamResult')
external void _resolveStreamResult(WasmExternRef capability, WasmExternRef? envelope, WasmI32 done);

final class _StreamSnapshot {
  final WasmExternRef envelope;
  _StreamSnapshot(this.envelope);
  void release() { _releaseStreamItem(envelope); }
}
final class _StreamHostError implements Exception {
  final WasmExternRef envelope;
  _StreamHostError(this.envelope);
}
NapiStream<dynamic, _StreamSnapshot> _streamState(WasmExternRef reference) =>
    reference.internalize().toObject() as NapiStream<dynamic, _StreamSnapshot>;

@pragma('wasm:export', 'napi:stream:roots')
WasmExternRef _streamRoots(WasmExternRef reference) =>
    WasmAnyRef.fromObject(_streamState(reference).retainedInputs).externalize();

@pragma('wasm:export', 'napi:stream:finish')
void _finishStreamCreation(WasmExternRef reference, WasmI32 published) {
  _streamState(reference).finishCreation(published.toIntSigned() != 0);
}

@pragma('wasm:export', 'napi:stream:read')
void _readStream(WasmExternRef capability, WasmExternRef reference, WasmI32 closing) {
  final state = _streamState(reference);
  _observeFuture(closing.toIntSigned() == 0 ? state.next() : state.return_(),
      capability, 'Stream iteration', (delivery) {
    _attachStreamDelivery(capability, externRefForJSAny((() { delivery.release(); }).toJS)!,
        externRefForJSAny(((JSAny envelope) {
          state.deliveryFailed(_StreamHostError(externRefForJSAny(envelope)!), StackTrace.current);
        }).toJS)!);
    switch (delivery.kind) {
      case StreamDeliveryKind.value:
        _resolveStreamResult(capability, delivery.value!.envelope, WasmI32.fromInt(0));
      case StreamDeliveryKind.done:
        _resolveStreamResult(capability, null, WasmI32.fromInt(1));
      case StreamDeliveryKind.error:
        final error = delivery.error!;
        if (error is _StreamHostError) {
          _throwStreamError(error.envelope);
        } else if (error is StreamBufferOverflow) {
          _throwStreamOverflow(externRefForJSAny(error.message.toString().toJS)!,
              externRefForJSAny(_stackMessage(delivery.stack ?? StackTrace.empty).toJS)!);
        } else {
          _normalizeFutureError(error, delivery.stack ?? StackTrace.empty, 'Stream iteration');
        }
    }
  });
}
''';

/// The host owns the release callback so JS conversion failures also release
/// accepted operations, including errors that bypass Dart exception handlers.
const resourceEntrypointPrelude = r'''
final class _ResourcePolicyViolation implements Exception {
  const _ResourcePolicyViolation();
}

WasmExternRef? _normalizeResourceError(Object error) {
  if (error is _ResourcePolicyViolation) {
    _resourcePolicyError();
    return null;
  }
  return _normalizeError(error);
}

void _failResourceFuture(WasmExternRef capability, Object error, StackTrace stack, String context) {
  if (error is _ResourcePolicyViolation) { _resourcePolicyError(); return; }
  _failFuture(capability, error, stack, context);
}

void _retainResourceReference(ResourceOperation operation, JSAny? reference, [JSAny? defaultId]) {
  if (defaultId != null) {
    _visitValueDefaultReferences((defaultId as JSString).toDart, (value) {
      _retainResourceReference(operation, WasmAnyRef.fromObject(value).externalize().toJS);
    });
    return;
  }
  if (reference == null) return;
  try {
    operation.retain(_resourceControl(externRefForJSAny(reference)!.internalize().toObject()));
  } catch (error) { _normalizeResourceError(error); }
}

@pragma('wasm:export', 'napi:resource:begin')
WasmExternRef? _beginResourceOperation(WasmExternRef capability, WasmExternRef? reference, WasmI32 cleanup) {
  try {
    final control = reference.isNull ? null : _resourceControl(reference!.internalize().toObject());
    final exempt = cleanup.toIntSigned() != 0;
    final operation = ResourceOperation(exempt: exempt ? control : null);
    _attachResourceOperation(capability,
        externRefForJSAny((() { operation.release(); }).toJS)!,
        externRefForJSAny(((JSAny? value, [JSAny? defaultId]) { _retainResourceReference(operation, value, defaultId); }).toJS)!);
    if (!exempt) operation.retain(control);
    return WasmAnyRef.fromObject(operation).externalize();
  } catch (error) { return _normalizeResourceError(error); }
}

@pragma('wasm:import', 'napi.attachResourceOperation')
external void _attachResourceOperation(WasmExternRef capability, WasmExternRef release, WasmExternRef retain);
@pragma('wasm:import', 'napi.readResourceValue')
external WasmExternRef? _readResourceValue(WasmExternRef capability, WasmExternRef? value, WasmI32 context);
@pragma('wasm:import', 'napi.activateResourceOperation')
external void _activateResourceOperation(WasmExternRef capability, WasmI32 active);
@pragma('wasm:import', 'napi.bindCleanup')
external WasmI32 _bindCleanup(WasmExternRef capability, WasmExternRef control);
@pragma('wasm:import', 'napi.resourcePolicyError')
external void _resourcePolicyError();
''';
